import React, { useState, useMemo, useEffect } from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

const COLS = [
  { key: "id", label: "ID" },
  { key: "name", label: "Name" },
  { key: "access_type", label: "Access Type" },
  { key: "email", label: "Email" },
  { key: "location", label: "Location" },
  { key: "status", label: "Status" },
  { key: "last_login", label: "Last Login" },
  { key: "chat_tag", label: "Chat Tag" },
  { key: "group_tag", label: "Group Tag" },
  { key: "last_updated", label: "Last Updated" }
];

function pad(n) { return String(n).padStart(2, "0"); }
function fmt(s, shortYear) {
  if (!s) return "";
  const d = new Date(s);
  if (isNaN(d.getTime())) return "";
  const y = shortYear ? String(d.getFullYear()).slice(-2) : d.getFullYear();
  let h = d.getHours(); const ap = h >= 12 ? "PM" : "AM"; h = h % 12 || 12;
  return pad(d.getMonth() + 1) + "/" + pad(d.getDate()) + "/" + y + " " + h + ":" + pad(d.getMinutes()) + " " + ap;
}

function App() {
  const [model, setModel] = useState(appsmith.model || {});
  const [sortKey, setSortKey] = useState("id");
  const [sortDir, setSortDir] = useState("desc");
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(20);
  const [gotoVal, setGotoVal] = useState("");

  useEffect(() => {
    const update = () => setModel({ ...(appsmith.model || {}) });
    update();
    if (typeof appsmith.onModelChange === "function") appsmith.onModelChange(update);
    const id = setInterval(update, 400);
    return () => clearInterval(id);
  }, []);

  const data = (model && model.data) || [];

  const rows = useMemo(() => {
    const list = data.slice();
    list.sort(function (a, b) {
      if (sortKey === "id") { const av = Number(a.id), bv = Number(b.id); return sortDir === "asc" ? av - bv : bv - av; }
      if (sortKey === "last_login") { const av = a.last_login ? new Date(a.last_login).getTime() : 0, bv = b.last_login ? new Date(b.last_login).getTime() : 0; return sortDir === "asc" ? av - bv : bv - av; }
      const av = (a[sortKey] == null ? "" : String(a[sortKey])), bv = (b[sortKey] == null ? "" : String(b[sortKey]));
      return sortDir === "asc" ? av.localeCompare(bv) : bv.localeCompare(av);
    });
    return list;
  }, [data, sortKey, sortDir]);

  useEffect(() => { setPage(1); }, [data.length]);

  const totalPages = Math.max(1, Math.ceil(rows.length / pageSize));
  const safePage = Math.min(page, totalPages);
  const start = (safePage - 1) * pageSize;
  const pageRows = rows.slice(start, start + pageSize);

  const onSort = (k) => { if (k === sortKey) setSortDir(sortDir === "asc" ? "desc" : "asc"); else { setSortKey(k); setSortDir("asc"); } };
  const goToPage = (p) => { if (!Number.isFinite(p)) return; setPage(Math.max(1, Math.min(totalPages, Math.floor(p)))); };
  const onGotoSubmit = (e) => { if (e.key === "Enter") { const n = parseInt(gotoVal, 10); if (!isNaN(n)) goToPage(n); setGotoVal(""); } };
  const openUser = (row) => {
    appsmith.updateModel({ selectedUserId: row.id, selectedUserName: row.name });
    if (typeof appsmith.triggerEvent === "function") appsmith.triggerEvent("onUserOpen");
  };

  if (model.isLoading) return React.createElement("div", { className: "skel" }, "Loading users...");

  const arrows = (k) => React.createElement("span", { className: "sort" },
    React.createElement("span", { className: (sortKey === k && sortDir === "asc") ? "active" : "" }, "▲"),
    React.createElement("span", { className: (sortKey === k && sortDir === "desc") ? "active" : "" }, "▼"));

  const statusCell = (s) => {
    const map = { Active: "#22c55e", Inactive: "#64748b" };
    const filled = s !== "Pending";
    const color = map[s] || "#94a3b8";
    const dotStyle = filled ? { background: color } : { background: "transparent", border: "2px solid #94a3b8", width: "6px", height: "6px" };
    return React.createElement("span", { className: "stat" },
      React.createElement("span", { className: "dot", style: dotStyle }), s || "");
  };

  const cell = (r, key) => {
    if (key === "id") return React.createElement("a", { className: "idlink", onClick: () => openUser(r) }, r.id);
    if (key === "status") return statusCell(r.status);
    if (key === "last_login") return r.last_login ? fmt(r.last_login, true) : "-";
    if (key === "chat_tag") return r.chat_tag ? React.createElement("span", { className: "chk" }, "✓") : "";
    if (key === "group_tag") return "";
    if (key === "last_updated") return r.modified_by_name ? (r.modified_by_name + ", " + fmt(r.modified_at, false)) : "Admin System";
    const v = r[key];
    return v == null ? "" : String(v);
  };

  return React.createElement("div", { className: "wrap" },
    React.createElement("div", { className: "meta" }, rows.length + " Records"),
    React.createElement("div", { className: "scroll" },
      React.createElement("table", { className: "tbl" },
        React.createElement("thead", null,
          React.createElement("tr", null,
            COLS.map((c) => React.createElement("th", { key: c.key, onClick: () => onSort(c.key) }, c.label, arrows(c.key))))),
        React.createElement("tbody", null,
          pageRows.length === 0
            ? React.createElement("tr", null, React.createElement("td", { className: "empty", colSpan: COLS.length }, "No users found"))
            : pageRows.map((r, i) => React.createElement("tr", { key: (r.id != null ? r.id : i) },
                COLS.map((c) => React.createElement("td", { key: c.key }, cell(r, c.key)))))))),
    React.createElement("div", { className: "pager" },
      React.createElement("button", { className: "pbtn", disabled: safePage <= 1, onClick: () => goToPage(safePage - 1) }, "‹"),
      React.createElement("span", { className: "pnum" }, safePage),
      React.createElement("span", { className: "gotolbl" }, "of " + totalPages),
      React.createElement("button", { className: "pbtn", disabled: safePage >= totalPages, onClick: () => goToPage(safePage + 1) }, "›"),
      React.createElement("span", { className: "gotolbl" }, "Go to"),
      React.createElement("input", { className: "goto", type: "number", min: 1, max: totalPages, value: gotoVal, onChange: (e) => setGotoVal(e.target.value), onKeyDown: onGotoSubmit, placeholder: String(safePage) }),
      React.createElement("select", { className: "psize", value: pageSize, onChange: (e) => { setPageSize(Number(e.target.value)); setPage(1); } }, [10, 20, 30, 40, 50, 100].map(function (n) { return React.createElement("option", { key: n, value: n }, n + "/page"); }))));
}

ReactDOM.render(React.createElement(App, null), document.getElementById("root"));

